STRAIN=S+[['古法语 estreindre 的词干 → 中古英语 streinen → strain','捆紧、用力 → 拉伤、使吃力；过滤']]
RE=S+[['拉丁语 re- + stringere → restringere','往回拉紧 → 限制、抑制']]
RESTRICT=RE+[['拉丁语 restrictus → 英语 restrict','受约束的 → 限定范围']]
RESTRAIN=RE+[['古法语 restraindre / restreindre → 英语 restrain','勒住、控制住']]
CON=S+[['拉丁语 con- + stringere → constringere','一起捆紧、束缚']]
CONSTRAIN=CON+[['古法语 constreindre → 英语 constrain','约束、使行动受限；迫使']]
STRINGENT=S+[['拉丁语 stringens，词干 stringent- → 英语 stringent','收紧的 → 严厉、要求很高']]
ASTR=S+[['拉丁语 ad- + stringere → astringere / adstringere','牢牢收紧'],['拉丁语 astringens → 可能经中古法语 → 英语 astringent','使收缩的 → 涩口；尖锐']]
DISTBASE=S+[['拉丁语 dis- + stringere → distringere → districtus','分开拉扯、约束；后有强迫义']]
DIST=DISTBASE+[['分别经古法语 destresse〔名〕、destresser〔动〕 → 英语 distress','困厄、痛苦；使痛苦']]
STRESS=S+[['拉丁语 strictus 及其衍生形式 → 古法语 estrece / estrecier 等','紧、狭窄 → 压迫、施压'],['英语 stress〔名、动〕；也部分来自 distress 的缩短','压力、强调、重音；不是仅由英语名词派生出动词']]
W=[
E('strict','/strɪkt/','严格的；严密的；完全遵守规则的','把规则拉得很紧，不随便给人钻空子。','来自拉丁 stringere 的过去分词 strictus；现代英语中不是 str- + -ict。',STRICT,'a strict teacher 要求学生守规矩；strict limits 留的余地很小。in the strict sense 指按最准确、最窄的定义来讲。严不一定等于凶或不公平。','strict with somebody；strict about deadlines；in strict confidence。','strict 强调要求和执行；harsh 强调苛刻、令人难受，严格的老师也可以很温和。',('She is strict about deadlines but happy to answer questions.','她严格要求按时完成，但很乐意解答问题。'),('In the strict sense, a square is also a rectangle.','严格说来，正方形也是长方形。'),sources=['https://www.etymonline.com/word/strict','https://www.oxfordlearnersdictionaries.com/definition/english/strict']),
E('strictly','/ˈstrɪktli/','严格地；完全地；仅仅','把范围收得很窄：按规定一点不松，或只允许某一种用途。','strict + -ly。',STRICT+[['英语 strict + -ly → strictly','严格的 → 严格地；限定在某范围内']],'strictly prohibited 是严禁；strictly for staff 是仅供员工。strictly speaking 用来补一句更精确的说法，不是准备严厉地讲话。','strictly speaking；strictly confidential；strictly for personal use。','strictly 可以表示 only；strictly for research 强调用途边界，不是在评价研究有多严厉。',('This entrance is strictly for staff.','这个入口仅供员工使用。'),('Strictly speaking, the report describes a trend rather than proving its cause.','严格说来，这份报告描述了趋势，并没有证明其成因。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/strictly','https://en.wiktionary.org/wiki/strictly#English']),
E('strictness','/ˈstrɪktnəs/','严格；严厉程度','规则或执行者到底把要求卡得多紧。','strict + -ness，把形容词变成性质名词。',STRICT+[['英语 strict + -ness → strictness','严格这种性质或程度']],'可以比较两所学校的 strictness，也能谈规则执行的严格程度。它说的是标准与执行，不自动包含责骂、惩罚或冷漠。','the strictness of the rules；a reputation for strictness；excessive strictness。','severity 可以说病情、天气或惩罚有多严重；strictness 通常围绕遵守要求。',('The school is known for the strictness of its attendance rules.','这所学校以出勤规定严格著称。'),('His strictness at work does not prevent him from being kind.','他工作上要求严格，但待人仍然友善。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/strictness','https://en.wiktionary.org/wiki/strictness#English']),
E('strain','/streɪn/','使吃力；拉伤；过滤；压力、负担；品种、菌株','压力这一支像把东西绷得太紧；菌株那一支说的是同一谱系的一类，来源另算。','拉紧、过滤义经古法语 estreindre 接拉丁 stringere；品种义接古英语 strēon 一系，后来拼写受前者影响，不能把菌株解释成被拉紧的细菌。',STRAIN+[['另一来源：古英语 strēon → 中古英语 streen 等 → strain','繁衍、谱系 → 品种、菌株；不接前面的拉紧路线']],'strain your back 是用力过头伤到背；put a strain on finances 是让财力吃紧。strain the soup 是用滤网滤掉固体。a strain of bacteria 则是一种菌株，属于另一个来源。','under strain；strain a muscle；strain something through a sieve；a new strain。','日常 stress 与 strain 都可说压力；力学中 stress 是应力，strain 是形变相对原尺寸的应变，不能直接互换。',('The unexpected repairs put a strain on our budget.','意外的修理开支让我们的预算吃紧。'),('Strain the soup through a fine sieve before serving.','上桌前用细筛过滤汤。'),('The researchers compared two strains of the same bacterium.','研究人员比较了同一种细菌的两个菌株。'),sources=['https://www.etymonline.com/word/strain','https://www.oxfordlearnersdictionaries.com/definition/english/strain_1','https://www.oxfordlearnersdictionaries.com/definition/english/strain_2']),
E('strained','/streɪnd/','紧张的；勉强的；拉伤的；过滤过的','被绷紧以后，动作、声音或关系都不太自然了。','strain + -ed，既是过去分词，也常作形容词；过滤义同样可以形成 strained。',STRAIN+[['英语 strain + -ed → strained','用力、施压后的 → 紧张、勉强；滤过的']],'a strained smile 是硬挤出来的笑；strained relations 是相处紧张。strained soup 则只是滤过的汤，并没有“汤很焦虑”的意思。','a strained voice；strained relations；a strained muscle。','stressed 多说人在压力下；strained 更常说关系、表情、声音不自然，也可描述肌肉受伤。',('She gave a strained smile and changed the subject.','她勉强笑了笑，转移了话题。'),('Relations between the two teams became strained after the dispute.','争执后，两个团队的关系变得紧张。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/strained','https://www.etymonline.com/word/strain']),
E('strainer','英 /ˈstreɪnə/；美 /ˈstreɪnər/','滤网；过滤器','让液体过去，把不想要的固体留下的工具。','strain 的过滤义 + -er；这里 -er 表工具，不是执行动作的人。',STRAIN+[['英语 strain + -er → strainer','过滤用的器具']],'厨房里的 tea strainer 留住茶叶；网眼粗细决定能拦住多大的颗粒。它不一定是复杂机器，小小的茶滤也算。','a tea strainer；a fine mesh strainer；pour through a strainer。','sieve 常指筛网，可筛粉也可滤液体；strainer 的命名更突出把液体中的固体滤出来。',('Pour the tea through a strainer to catch the loose leaves.','把茶倒过茶滤，滤掉散开的茶叶。'),('I used a fine strainer to remove the seeds from the sauce.','我用细滤网滤掉了酱汁里的籽。'),sources=['https://www.etymonline.com/word/strainer','https://www.oxfordlearnersdictionaries.com/definition/english/strainer']),
E('restrict','/rɪˈstrɪkt/','限制；限定','给行动、数量或使用范围画一条不能随便跨过的线。','借自拉丁 restrictus，来自 re- + stringere；re- 在这条历史里表示往回收紧，不是再严格一次。',RESTRICT,'restrict access to staff 是只让员工进入；restrict spending 是把开销压在一定范围。restrict 不一定完全禁止，只是缩小可做的空间。','restrict access；restrict something to somebody；restrict somebody’s freedom。','ban 是禁止；restrict 可以只是减少、限定对象或限定时间。',('The company restricts access to these files to the finance team.','公司只允许财务团队访问这些文件。'),('A tight schedule restricts how much we can change.','紧张的日程限制了我们能调整的幅度。'),sources=['https://www.etymonline.com/word/restrict','https://www.oxfordlearnersdictionaries.com/definition/english/restrict']),
E('restriction','/rɪˈstrɪkʃən/','限制；限制条件','那条把人、资源或活动卡住的规定，也可以指受限的状态。','现代可对照 restrict + -ion；历史上经法语 restriction 或直接从晚期拉丁 restrictio 借入，英语名词早于 restrict 动词。',RE+[['晚期拉丁 restrictio → 法语 restriction / 直接借入 → 英语 restriction','限制、约束的名词支线']],'a restriction on travel 是对出行的限制；lift restrictions 是解除限制。dietary restrictions 是饮食禁忌或限制条件，不必来自政府规定。','impose restrictions；lift restrictions；restrictions on access；dietary restrictions。','a restriction 是具体边界或限制措施；a rule 可以规定很多事，不都在缩小自由。',('There are no restrictions on how many books you can reserve.','预约图书的数量没有限制。'),('Please tell us about any dietary restrictions before the event.','活动前请告知我们您的饮食禁忌或限制。'),sources=['https://www.etymonline.com/word/restriction','https://www.oxfordlearnersdictionaries.com/definition/english/restriction']),
E('restrictive','/rɪˈstrɪktɪv/','限制性的；约束过多的','规定把活动空间收得很小，让人觉得不好施展。','现代与 restrict + -ive 对照；历史接中古拉丁 restrictivus，词典也记录法语 restrictif 参与，不是必须由英语 restrict 现造。',RE+[['中古拉丁 restrictivus / 法语 restrictif → 英语 restrictive','使收紧的 → 限制性的']],'a restrictive policy 常带着“限制太多”的评价。语法中的 restrictive clause 是限定所指范围的从句，例如 the people who live here，who live here 指明是哪群人。','restrictive rules；a restrictive agreement；a restrictive clause。','restricted 说已经受限；restrictive 说某物在施加限制。',('The team found the approval process too restrictive.','团队觉得审批流程限制太多。'),('A restrictive clause helps identify exactly which person or thing is meant.','限制性从句帮助明确所说的究竟是哪一个人或事物。'),sources=['https://www.etymonline.com/word/restrictive','https://www.oxfordlearnersdictionaries.com/definition/english/restrictive','https://en.wiktionary.org/wiki/restrictive#English']),
E('restricted','/rɪˈstrɪktɪd/','受限制的；限特定人员使用的','门或范围已经收窄，只剩一部分人、动作或空间可用。','restrict + -ed；从过去分词发展为描述状态的形容词。',RESTRICT+[['英语 restrict + -ed → restricted','被限制的 → 使用、活动范围受限']],'restricted access 是访问受限；a restricted area 不是面积一定小，而是进入资格受限制。a restricted range of choices 则是真正可选项目少。','a restricted area；restricted access；restricted movement。','restrictive 强调造成限制的东西；restricted 强调承受限制的人或范围。',('Only authorized staff may enter the restricted area.','只有获授权的员工可以进入限制区域。'),('The old software offers a restricted range of export options.','旧软件提供的导出选项很有限。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/restricted','https://www.etymonline.com/word/restricted']),
E('unrestricted','/ˌʌnrɪˈstrɪktɪd/','不受限制的；自由使用的','原先可能存在的数量、时间或权限限制，在所说的范围内没有设下。','un- + restricted；否定受限制的状态。',RESTRICT+[['英语 restricted → un- + restricted → unrestricted','受限的 → 无相应限制的']],'unrestricted access 让人在指定范围内自由访问，不自动意味着全世界所有资料都公开。看清后面的对象，才能知道到底放开了什么。','unrestricted access；unrestricted use；unrestricted movement。','unlimited 偏数量或程度没有上限；unrestricted 也可说没有身份、地点或用途方面的约束。',('Members have unrestricted access to the archive during opening hours.','会员在开放时间内可以自由查阅档案。'),('The grant allows unrestricted use of the funds within the project.','这笔资助允许在该项目范围内自由使用资金。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/unrestricted','https://en.wiktionary.org/wiki/unrestricted#English']),
E('constrain','/kənˈstreɪn/','约束；限制；迫使','像有一根绳子牵着，行动不能完全按自己的意思来。','经古法语 constreindre 接拉丁 constringere；con- 表一起，stringere 表捆紧。',CONSTRAIN,'时间、预算、设备都能 constrain what we do。be constrained to do something 在正式语体也可表示迫于情势不得不做；不是这个动作被禁止了。','be constrained by a budget；constrain growth；feel constrained to respond。','restrict 常突出设定界限；constrain 常突出环境或条件牵制，有时还会把人逼向某种行动。',('A shortage of staff constrains our ability to take on new projects.','人员不足限制了我们承接新项目的能力。'),('I felt constrained to point out the error.','我觉得自己不得不指出这个错误。'),sources=['https://www.etymonline.com/word/constrain','https://www.oxfordlearnersdictionaries.com/definition/english/constrain']),
E('constraint','/kənˈstreɪnt/','约束；限制条件；拘束','挡在方案面前的一道边界：时间只有这么多，钱只有这么多。','借自古法语 constreinte，与 constreindre 的分词有关，远接拉丁 constringere；不是英语 constrain 直接加一个 -t 的通用规则。',CON+[['拉丁 constrictus 一系 → 古法语 constreinte → 英语 constraint','被束缚的状态 → 限制条件']],'time constraints 是时间限制；work within constraints 是在既定条件里想办法。单数 constraint 可以是一条约束，泛指拘束状态时也可不可数。','time constraints；budget constraints；constraints on growth；within these constraints。','limitation 可指能力本身的短处；constraint 更像任务必须满足或无法绕开的条件。',('We chose a smaller venue because of budget constraints.','受预算限制，我们选了较小的场地。'),('The design meets all the constraints without sacrificing readability.','这个设计满足所有约束，同时保持易读。'),sources=['https://www.etymonline.com/word/constraint','https://www.oxfordlearnersdictionaries.com/definition/english/constraint']),
E('constrained','/kənˈstreɪnd/','受约束的；拘谨的；不自然的','外在条件卡着你，或者心里放不开，动作和话都收着。','constrain + -ed，描述受限制后的状态。',CONSTRAIN+[['英语 constrain + -ed → constrained','受到牵制 → 受限、拘谨']],'资源 constrained 是做不了更多；a constrained smile 则像顾虑很多、不敢自然笑。技术语境的 constrained optimization 指在约束条件下求最优解。','constrained by time；a constrained manner；a constrained environment。','strained 常强调紧张、用力过头；constrained 更突出被条件或自我克制束住。',('Our choices are constrained by the equipment we already have.','我们现有的设备限制了可选方案。'),('Her reply was polite but constrained.','她的答复很礼貌，却显得拘谨。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/constrained','https://en.wiktionary.org/wiki/constrained#English']),
E('unconstrained','/ˌʌnkənˈstreɪnd/','不受约束的；自由自在的','牵着行动的绳子松开了，想法或表现能自由展开。','un- + constrained。',CONSTRAIN+[['英语 constrained → un- + constrained → unconstrained','受约束的 → 不受相应约束的']],'unconstrained imagination 指不被现实限制的想象；unconstrained by cost 是暂且不受费用牵制。它描述所谈的约束被拿开，不是永远没有任何边界。','unconstrained by tradition；unconstrained creativity；unconstrained optimization。','unrestricted 更常说外部许可或范围开放；unconstrained 常说想法、行动或数学问题没有给定约束。',('The first sketches were unconstrained by practical concerns.','最初的草图没有受到实际条件的束缚。'),('Children often approach the problem with unconstrained imagination.','孩子们常用自由奔放的想象来处理这个问题。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/unconstrained','https://en.wiktionary.org/wiki/unconstrained#English']),
E('constrict','/kənˈstrɪkt/','使收缩；勒紧；限制发展','把原本较宽的通道或空间向里收，越收越窄。','来自拉丁 constrictus，或从更早的英语 constriction 反构；与 constrain 同接 constringere，但不能把英语 constrain 当祖先。',CON+[['两种近源：拉丁 constrictus 直接借入；或英语 constriction 反构 → constrict','使缩紧、变窄']],'血管、瞳孔可以 constrict；紧衣服会 constrict movement。它比普通 limit 更容易让人想到空间被勒小、流动被挤住。','constrict blood vessels；constrict movement；pupils constrict。','constrain 偏条件牵制；constrict 更突出实际变窄或像被勒住的感觉。',('The tight collar constricted his movement.','紧衣领限制了他的活动。'),('The opening constricts near the end of the pipe.','管子接近末端处的开口变窄。'),sources=['https://www.etymonline.com/word/constrict','https://www.oxfordlearnersdictionaries.com/definition/english/constrict']),
E('constriction','/kənˈstrɪkʃən/','收缩；缩窄；狭窄处','东西被勒紧的过程，或者被勒出来的那一段窄口。','现代可对照 constrict + -ion；历史借自拉丁 constrictio，英语名词早于动词 constrict。',CON+[['拉丁 constrictio → 英语 constriction','捆紧、收缩的名词支线']],'a constriction in a tube 是管内的狭窄处；a feeling of constriction 是像被勒住的感觉。它不只是抽象规定，常有真实的空间收窄。','a constriction in a passage；constriction of blood vessels；a sense of constriction。','restriction 可以是一条规定；constriction 常是物体、通道的实际缩窄或身体的紧缩感。',('A constriction in the tube reduced the flow of water.','管中的一处狭窄降低了水流量。'),('The heavy scarf gave her a feeling of constriction around the neck.','厚重的围巾让她觉得脖子周围有些紧束。'),sources=['https://www.etymonline.com/word/constriction','https://www.oxfordlearnersdictionaries.com/definition/english/constriction']),
E('stringent','/ˈstrɪndʒənt/','严格的；严厉的；要求很高的','标准拧得很紧，必须达到很高要求才能过关。','借自拉丁 stringens 的词干 stringent-，是 stringere 的现在分词；不是英语 string“绳子”加后缀。',STRINGENT,'早期英语曾说收缩、涩口，后来常说法规、审查和安全标准严。stringent requirements 强调要求很高；a stringent budget 也可说经费卡得很紧。','stringent standards；stringent checks；stringent conditions。','strict 可形容老师、家长；stringent 更常修饰制度、标准、要求，语体也更正式。',('The equipment must pass stringent safety tests.','这套设备必须通过严格的安全测试。'),('The lender imposed stringent conditions on the loan.','贷款方为这笔贷款设定了严格条件。'),sources=['https://www.etymonline.com/word/stringent','https://www.oxfordlearnersdictionaries.com/definition/english/stringent']),
E('stringently','/ˈstrɪndʒəntli/','严格地；严厉地','把高要求真正落实到每一次检查和执行上。','stringent + -ly。',STRINGENT+[['英语 stringent + -ly → stringently','严格的 → 严格地执行、控制']],'stringently tested 是按高标准检测；stringently enforced 是不轻易放过不合要求的情况。常与监管、执行、检验搭配。','stringently tested；stringently enforced；stringently controlled。','strictly 更常见，也能表仅限；stringently 通常不表示“仅仅”，而突出高标准严执行。',('Each component is stringently tested before assembly.','每个部件在组装前都经过严格检测。'),('The new rules will be stringently enforced across all branches.','所有分支机构都将严格执行新规定。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/stringently','https://en.wiktionary.org/wiki/stringently#English']),
E('stringency','/ˈstrɪndʒənsi/','严格程度；严厉性；财务紧缩','要求究竟卡得有多紧；财务语境还可指钱很紧、开支受压。','stringent + -cy，形容词词尾 -ent 对应名词 -ency。',STRINGENT+[['英语 stringent → stringency','严格的 → 严格程度、紧缩状态']],'the stringency of tests 是测试的严格程度。financial stringency 是资金紧张带来的节约、控制开支，不是“财务人员性格严厉”。','regulatory stringency；the stringency of checks；financial stringency。','strictness 常说人或规则有多严格；stringency 更偏政策、标准和经济条件的严紧程度。',('The stringency of the checks increased after the incident.','事件之后，检查的严格程度提高了。'),('A period of financial stringency forced the museum to delay repairs.','一段资金紧张的时期迫使博物馆推迟修缮。'),sources=['https://www.etymonline.com/word/stringency','https://www.oxfordlearnersdictionaries.com/definition/english/stringency']),
E('astringent','/əˈstrɪndʒənt/','涩口的；有收敛作用的；尖锐刻薄的；收敛剂','喝浓茶时嘴里发干、发紧的感觉，比单纯苦更能抓住这个词。','拉丁 ad- + stringere → astringere，接现在分词 astringens；可能经中古法语进入英语。',ASTR,'涩味会让口腔感觉收紧；护肤品中的 astringent 是收敛剂的名称。比喻评论 astringent，则像一句话尖锐得让人一缩。','an astringent taste；an astringent lotion；astringent criticism。','bitter 是苦，astringent 更突出干涩、紧绷的口感；两种感觉可能同时出现。',('The tea had a strong, astringent taste.','这茶有明显的涩味。'),('Her astringent review exposed the weaknesses of the argument.','她尖锐的评论揭出了论证中的薄弱之处。'),sources=['https://www.merriam-webster.com/dictionary/astringent','https://www.oxfordlearnersdictionaries.com/definition/english/astringent']),
E('astringency','/əˈstrɪndʒənsi/','涩感；收敛性；尖锐性','把涩口、收紧或尖锐的性质单独拿出来说。','astringent 的名词形式，-ent 对应 -ency；不是另一个词根。',ASTR+[['英语 astringent → astringency','收紧、涩口的 → 涩感、收敛性']],'谈茶或葡萄酒时，astringency 是口腔干涩、发紧的感觉；谈文字时可以指不留情面的尖锐。它不等同酸度，也不是香气。','the astringency of tea；reduce astringency；a certain astringency in the writing。','bitterness 是苦味；astringency 更像嘴里被收紧的触感，品尝时要分开。',('Longer steeping increased the astringency of the tea.','延长浸泡时间让茶的涩感更重。'),('There is an astringency in her writing that keeps it from becoming sentimental.','她的文字带着几分尖锐，因此不显得感伤滥情。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/astringency','https://en.wiktionary.org/wiki/astringency#English']),
E('restrain','/rɪˈstreɪn/','制止；约束；克制','在动作或冲动冲出去之前，把它拉回来。','经古法语 restraindre、restreindre 接拉丁 restringere；与 restrict 同源，借入路线不同。',RESTRAIN,'restrain someone from doing 是阻止某人做；restrain anger 是忍住怒气。可以真的按住人，也可以靠自制让自己不发作。','restrain somebody from doing；restrain one’s anger；restrain spending。','restrict 常限定范围；restrain 更突出把正在或可能发生的动作压住。',('She managed to restrain her laughter during the meeting.','她在会议上设法忍住了笑。'),('His colleague restrained him from sending an angry email.','同事劝住了他，没有让他发出那封气头上的邮件。'),sources=['https://www.etymonline.com/word/restrain','https://www.oxfordlearnersdictionaries.com/definition/english/restrain']),
E('restraint','/rɪˈstreɪnt/','克制；约束；约束装置','可以是心里收住的一把闸，也可以是真的把身体固定住的装置。','来自古法语 restreinte，是 restraindre 的分词名词化；现代和 restrain 对照记忆，不套用随意加 -t 的规则。',RE+[['古法语 restraindre → restreinte → 英语 restraint','拉住、限制 → 约束、自制；约束物']],'show restraint 是不把情绪或权力用过头；restraints on spending 是开支限制。a child restraint 是儿童约束装置，属于具体可数义。','show restraint；exercise restraint；restraints on spending；a safety restraint。','constraint 常说必须面对的条件；restraint 更常说主动克制、阻拦或固定装置。',('He showed admirable restraint when the discussion became personal.','讨论开始针对个人时，他表现出了令人佩服的克制。'),('The ride has a padded restraint that locks across the passenger’s lap.','这个游乐设施有一根带软垫的约束杆，会锁在乘客腿部上方。'),sources=['https://www.etymonline.com/word/restraint','https://www.oxfordlearnersdictionaries.com/definition/english/restraint']),
E('restrained','/rɪˈstreɪnd/','克制的；节制的；不张扬的','有情绪或有装饰空间，但收着表达，不把音量和排场推满。','restrain + -ed，从受控制的状态发展出自制、简约的评价。',RESTRAIN+[['英语 restrain + -ed → restrained','收住了的 → 克制、不过分']],'a restrained response 不激烈；restrained colours 不花哨。也可以字面说身体被固定或动作受控，要看具体对象。','a restrained response；restrained enthusiasm；restrained elegance。','constrained 有时显得不自在；restrained 可以是有意识、得体的克制，并不勉强。',('She gave a restrained response to the criticism.','她对批评作出了克制的回应。'),('The room has a restrained elegance, with soft colours and simple furniture.','房间以柔和色彩和简洁家具呈现出低调的优雅。'),sources=['https://www.etymonline.com/word/restrained','https://www.oxfordlearnersdictionaries.com/definition/english/restrained']),
E('unrestrained','/ˌʌnrɪˈstreɪnd/','不受约束的；纵情的；不加克制的','原本收着的劲儿完全放开了，可能畅快，也可能失去分寸。','un- + restrained。',RESTRAIN+[['英语 restrained → un- + restrained → unrestrained','被控制的 → 尽情流露、未受约束']],'unrestrained laughter 是放声大笑；unrestrained spending 是不加节制地花钱。这个词本身不保证好坏，要看释放的是喜悦还是破坏力。','unrestrained joy；unrestrained laughter；unrestrained growth。','unrestricted 常是许可或范围开放；unrestrained 更强调行为、情绪没有收着。',('The children greeted the news with unrestrained joy.','孩子们听到消息后尽情欢呼。'),('Unrestrained spending soon exhausted the project’s budget.','不加节制的开销很快耗尽了项目预算。'),sources=['https://www.etymonline.com/word/unrestrained','https://www.oxfordlearnersdictionaries.com/definition/english/unrestrained']),
E('stress','/stres/','压力；重音；强调；使紧张','把分量压到某个地方：压到人身上是压力，压到观点上是强调，压到音节上是重音。','名词和动词都有早期借入路线：部分缩自 distress，部分经法语紧、压迫一系接拉丁 strictus；不能只画名词变动词。',STRESS,'under stress 是承受压力；stress the importance 是强调重要性；word stress 是词重音。工程中的 stress 为应力，描述材料内单位面积上的内力，与形变量 strain 分工不同。','under stress；stress the need for something；put stress on a syllable。','pressure 可以是外部要求或物理压力；stress 常说受压状态。语音中 stress 指突出读的音节，不是整句声音越大越好。',('She is under a lot of stress because several deadlines fall on the same day.','几个截止日期挤在同一天，让她压力很大。'),('The speaker stressed the need for clear evidence.','发言者强调了明确证据的重要性。'),('In “table”, the stress falls on the first syllable.','table 这个词的重音落在第一个音节。'),sources=['https://www.etymonline.com/word/stress','https://www.oxfordlearnersdictionaries.com/definition/english/stress_1','https://www.oxfordlearnersdictionaries.com/definition/english/stress_2']),
E('stressful','/ˈstresfl/','令人紧张的；压力很大的','这件事会把压力加到人身上，让人难以放松。','stress + -ful，表示充满压力或带来压力。',STRESS+[['英语 stress + -ful → stressful','带来压力的']],'a stressful week 是一周的事情让人压力大；a stressful job 则是工作本身经常带来压力。一般用来描述情境，不说 I am stressful 表示自己紧张。','a stressful situation；a stressful journey；find something stressful。','stressful 是事情令人有压力；stressed 是人已经感到有压力。',('Moving house can be stressful even when everything goes well.','即使一切顺利，搬家也可能让人压力很大。'),('She finds large social events stressful.','她觉得大型社交活动很让人紧张。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/stressful','https://en.wiktionary.org/wiki/stressful#English']),
E('stressed','/strest/','感到压力的；重读的；受应力的','压力或重音已经落在这个人、材料或音节上了。','stress + -ed；词尾 -ed 在 /s/ 后读 /t/，不是额外一拍 /ɪd/。',STRESS+[['英语 stress + -ed → stressed','受到压力的；被强调、重读的']],'feel stressed 是心里绷着；a stressed syllable 是重读音节。工程里 stressed metal 是承受应力的金属，不能按人的情绪理解。','feel stressed；a stressed syllable；stressed materials。','stressed 是受压的一方；stressful 是造成压力的情境。',('I felt stressed before the presentation, but the questions went well.','演讲前我很紧张，不过提问环节进行得很顺利。'),('Mark the stressed syllable in each word.','标出每个词的重读音节。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/stressed','https://www.etymonline.com/word/stress']),
E('distress','/dɪˈstres/','痛苦；忧伤；危难；使痛苦','困难把人逼到难以承受的地步，既能是情绪痛苦，也能是真正遇险。','经古法语 destresse、destresser 接拉丁 distringere 一系，名动词分别借入；不是现代 dis- 否定 stress。',DIST,'in distress 可以是情绪崩溃，也可以是船只遇险；a distress signal 是求救信号。动词 distress someone 是让人难过；做旧家具的 distress 则从损坏、磨损义发展。','cause distress；in distress；a distress signal；distress somebody。','stress 可只是忙碌紧张；distress 通常更突出痛苦、悲伤或急难。',('The news caused considerable distress to the family.','这个消息让全家人十分痛苦。'),('A passing ship picked up their distress signal.','一艘经过的船收到了他们的求救信号。'),sources=['https://www.etymonline.com/word/distress','https://www.oxfordlearnersdictionaries.com/definition/english/distress_1','https://www.oxfordlearnersdictionaries.com/definition/english/distress_2']),
E('distressing','/dɪˈstresɪŋ/','令人痛苦的；令人难过的','事情本身像往心里压了一块重物，让看到、听到的人难受。','distress + -ing，用来描述造成痛苦的事物。',DIST+[['英语 distress + -ing → distressing','使痛苦 → 令人痛苦的']],'distressing news 是令人悲痛或不安的消息；不是消息自己在难过。日常更接近 upsetting，语气通常较重。','distressing news；a distressing experience；deeply distressing。','distressed 形容感到痛苦的人；distressing 形容造成痛苦的消息、经历或画面。',('The documentary contains some distressing scenes.','这部纪录片包含一些令人难过的画面。'),('It was distressing to see how much the town had changed after the flood.','看到洪水之后小镇变了这么多，令人痛心。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/distressing','https://en.wiktionary.org/wiki/distressing#English']),
E('distressed','/dɪˈstrest/','忧伤痛苦的；困窘的；做旧的','人是被困难压得难受；衣物或家具则可能是被刻意弄出磨损感。','distress + -ed；情绪义来自使痛苦，做旧义来自损坏、磨损的动词用法。',DIST+[['英语 distress + -ed → distressed','感到痛苦；另一用法：人为磨损过的']],'deeply distressed 是非常难过；distressed jeans 是磨破、做旧风格的牛仔裤。商业语境 distressed assets 常指因财务困境而承压的资产。','distressed by the news；distressed jeans；distressed furniture。','stressed 常是压力大；distressed 更像已经非常难过或陷入困难。做旧义与人的心理感受分开理解。',('She was deeply distressed by the loss of the old photographs.','旧照片丢失让她非常难过。'),('The shop sells distressed wooden tables with a deliberately worn finish.','这家店出售表面刻意做出磨损效果的木桌。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/distressed','https://www.etymonline.com/word/distress']),
]
L=[['拉丁语 labor','劳动、费力、辛苦；更早来源不确定']]
LV=L+[['拉丁语 laborare','劳动、努力']]
LABOR=L+[['分别经古法语 labor〔名〕、laborer〔动〕 → 英语 labor / labour','劳动、劳力；费力工作；分娩']]
LAB=LV+[['中世纪拉丁 laboratorium → 英语 laboratory','工作的地方 → 实验室']]
COL=LV+[['拉丁语 com- + laborare → collaborare','一起工作']]
COLLAB=COL+[['法语 collaborateur → 英语 collaborator；另有法语 collaborer、拉丁 collaboratus','先有合作者名词，以及相关法语、拉丁形式'],['英语 collaborate','可能从 collaborator 反构，或仿法语、拉丁语形成']]
ELA=LV+[['拉丁语 ex- + laborare → elaborare → elaboratus','费力做出来、加工完成'],['英语 elaborate〔形容词与动词分别借入〕','精心制作、复杂的；详细说明']]
LOR=L+[['拉丁语 laboriosus → 古法语 laborios → 英语 laborious','充满辛劳的 → 费时费力的']]
W += [
E('labor','英 /ˈleɪbə/；美 /ˈleɪbər/','劳动；劳动力；分娩；努力工作','把力气和时间投进去做事；既能说具体付出，也能把劳动者作为整体来谈。','名词经法语 labor 接拉丁 labor；动词经法语 laborer 接拉丁 laborare。labor 是常见美式拼写，labour 是常见英式拼写。',LABOR,'manual labor 是体力劳动；labor costs 是人工成本。go into labor 指开始分娩。动词 labor over a report 表示费劲打磨报告，labor under a misunderstanding 则是一直受错误认识影响。','manual labor；labor costs；go into labor；labor over a task。','work 范围最广；labor 更常突出付出、劳动者群体或劳资关系，分娩是独立常用义项。',('The estimate includes the cost of both materials and labor.','报价包含材料费和人工费。'),('She labored over the final paragraph until it sounded right.','她反复琢磨最后一段，直到读起来顺口。'),('He left work when he heard that his partner had gone into labor.','听说伴侣开始分娩后，他离开了工作岗位。'),sources=['https://www.etymonline.com/word/labor','https://www.oxfordlearnersdictionaries.com/definition/english/labour_1','https://www.oxfordlearnersdictionaries.com/definition/english/labour_2']),
E('labour','英 /ˈleɪbə/；美 /ˈleɪbər/','劳动；劳动力；分娩；费力工作〔英式拼写〕','和 labor 是同一个词，换的是拼写习惯，不是多出一种劳动。','与 labor 同源同义；英国通常保留 -our，美国通常写 -or，不能把 labour 说成另一个词根。',LABOR,'labour market 是劳动力市场；a labour of love 是出于热爱而费心完成的工作。大写 Labour 可以指名称中含 Labour 的工党，具体对象依国家、语境而定。','the labour market；a labour of love；labour over details；labour costs。','labour 与 labor 的差别主要是地区拼写。labourious 不是标准写法，对应形容词写 laborious。',('Restoring the boat was a labour of love for the whole family.','修复这条船是全家出于热爱而投入的一项工程。'),('The report examines changes in the local labour market.','报告研究了当地劳动力市场的变化。'),sources=['https://www.etymonline.com/word/labour','https://www.oxfordlearnersdictionaries.com/definition/english/labour_1']),
E('laborer','英 /ˈleɪbərə/；美 /ˈleɪbərər/','体力劳动者；劳工〔美式拼写〕','主要靠体力完成搬运、建筑、农务等工作的工人。','labor + -er，可对应 labourer；词形在中古英语已有，最终沿 labor 一系接拉丁 labor。',LABOR+[['英语 labor / labour + -er → laborer / labourer','做体力工作的人']],'a construction laborer 是建筑劳工；这个词描述工作类型，不是评价一个人的知识、价值或能力。现代语境通常不指所有办公室员工。','a construction laborer；a farm laborer；seasonal laborers。','worker 是更宽泛的工作者；laborer 通常让人想到体力劳动。',('The contractor hired several laborers to help clear the site.','承包商雇了几名劳工帮忙清理场地。'),('Her father worked as a farm laborer before opening a small shop.','她父亲开小店前做过农业劳工。'),sources=['https://www.etymonline.com/word/laborer','https://www.merriam-webster.com/dictionary/laborer']),
E('labourer','英 /ˈleɪbərə/；美 /ˈleɪbərər/','体力劳动者；建筑或农业劳工〔英式拼写〕','指用体力完成工作的人，在英国招聘和社会生活中常能看到。','labour + -er，和 laborer 是地区拼写变体；词尾 -er 标人。',LABOR+[['英语 labour + -er → labourer','从事体力劳动的人；美式通常写 laborer']],'a builder’s labourer 协助建筑工地上的工作；a day labourer 按日受雇。它不是所有劳动者的总称，谈整个劳动力群体通常用 labour 或 workforce。','a builder’s labourer；an agricultural labourer；a day labourer。','employee 说明受雇关系；labourer 说明工作类型，两者关注点不同。',('He found work as a builder’s labourer during the summer.','暑假里他找到了一份建筑劳工的工作。'),('The farm needs extra labourers during the harvest.','农场在收获季需要额外的劳工。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/labourer','https://www.etymonline.com/word/laborer']),
E('laboratory','英 /ləˈbɒrətri/；美 /ˈlæbrətɔːri/','实验室；实验研究场所','专门把想法拿来测试、观察和分析的地方。','借自中世纪拉丁 laboratorium，来自 laborare 的工作支线；不是现代英语 labor 随意接 -atory 后才产生。',LAB,'实验室常有仪器，也可以专做计算或语言训练。把一个地方叫 a laboratory for new ideas，是说它适合试验想法。英式通常重读第二音节，美式通常重读第一音节。','a research laboratory；laboratory tests；in the laboratory。','laboratory 指实验场所或研究设施；workshop 也能工作、制作，但不一定围绕实验验证。',('The samples were sent to a laboratory for analysis.','样本被送往实验室分析。'),('The small theatre became a laboratory for new performance ideas.','这家小剧场成了试验新表演想法的场所。'),sources=['https://www.etymonline.com/word/laboratory','https://www.oxfordlearnersdictionaries.com/definition/english/laboratory']),
E('lab','/læb/','实验室；实验课；拉布拉多犬〔另一个缩略义〕','把 laboratory 缩短成日常顺口的叫法；学生还会用它指一节实验课。','实验室义是 laboratory 的截短；表示狗的 Lab 则缩自 Labrador，另源，不能接到劳动词根。',LAB+[['英语 laboratory → lab','日常缩称：实验室、实验课'],['另源缩略：Labrador → Lab','拉布拉多犬；不接前面的实验室来源']],'the chemistry lab 可以是房间；a three-hour lab 可以是三小时实验课。a black Lab 则多半在说一只黑色拉布拉多犬，要看上下文。','a science lab；a lab report；a computer lab；a yellow Lab。','lab 与 laboratory 多数场合同义，前者更短。lab report 是实验报告，不是一般工作汇报。',('We have a chemistry lab every Thursday afternoon.','我们每周四下午有化学实验课。'),('Her yellow Lab waited quietly beside the door.','她的黄色拉布拉多犬安静地等在门边。'),sources=['https://www.etymonline.com/word/lab','https://www.oxfordlearnersdictionaries.com/definition/english/lab','https://www.merriam-webster.com/dictionary/lab']),
E('collaborate','/kəˈlæbəreɪt/','合作；协作；与占领者勾结','几个人把劳动接在一起，共同做出一件东西。','con- 在 l 前同化为 col-，接 laborare。英语近源有从 collaborator 反构、仿法语 collaborer、取拉丁 collaboratus 等解释，不把一种说法画定。',COLLAB,'collaborate with someone on a project 是和某人合作做项目。历史战争语境也可指与占领敌军合作，这时常带背叛意味；普通工作场合不带这种负面意思。','collaborate with somebody；collaborate on a project；collaborate closely。','cooperate 可以只是配合对方；collaborate 往往更强调一起创作、研究或完成共同成果。',('The designer collaborated with an engineer on the new chair.','设计师与一位工程师合作开发了这把新椅子。'),('Several schools collaborated to produce a shared set of teaching materials.','几所学校合作编写了一套共用教材。'),sources=['https://www.etymonline.com/word/collaborate','https://www.oxfordlearnersdictionaries.com/definition/english/collaborate']),
E('collaboration','/kəˌlæbəˈreɪʃən/','合作；合作成果；与敌方合作','重点放在共同工作的过程，或由共同工作做出来的作品。','借自法语 collaboration，接拉丁 collaborare；英语名词记录早于 collaborate，现代可对应动词 + -ion，但历史不能倒过来。',COL+[['法语 collaboration → 英语 collaboration','共同劳动 → 合作活动、合作成果']],'in collaboration with 表示与某人合作；a collaboration between two artists 可以是一件具体作品。占领史中的 collaboration 可能带有通敌含义，需要语境。','in collaboration with；close collaboration；a creative collaboration。','cooperation 可以不共享最终作品；collaboration 常把双方的工作交织成一个成果。',('The exhibition was developed in collaboration with local artists.','展览由本地艺术家共同参与策划。'),('The album is a collaboration between a singer and a string quartet.','这张专辑是歌手与一个弦乐四重奏组合的合作作品。'),sources=['https://www.etymonline.com/word/collaboration','https://www.oxfordlearnersdictionaries.com/definition/english/collaboration']),
E('collaborator','英 /kəˈlæbəreɪtə/；美 /kəˈlæbəreɪtər/','合作者；协作者；通敌者','不是只在旁边提意见，而是实际参与共同工作的人。','借自法语 collaborateur，接拉丁 collaborare 一系；英语这个人物名词比 collaborate 更早，不能简单写为英语动词先加 -or。',COL+[['拉丁 collaboratus 一系 → 法语 collaborateur → 英语 collaborator','一起工作的人']],'a longtime collaborator 是长期一起创作或研究的人。战争史里的 collaborator 也可指协助占领军的人，不能在所有语境都翻成积极的伙伴。','a close collaborator；a longtime collaborator；a research collaborator。','colleague 是同事；collaborator 是实际合作的人，可能来自另一家公司或机构。',('She thanked her longtime collaborator for his contribution to the film.','她感谢长期合作伙伴为这部电影所作的贡献。'),('The historian interviewed both resistance members and former collaborators.','历史学者采访了抵抗组织成员，也采访了曾与占领者合作的人。'),sources=['https://www.etymonline.com/word/collaborator','https://www.oxfordlearnersdictionaries.com/definition/english/collaborator']),
E('collaborative','/kəˈlæbərətɪv/','合作的；依靠共同参与的','工作方式是让参与者一起投入、互相接力，而不是各自闷头做完。','collaborate 的词基 + -ive，现代英语派生形容词。',COLLAB+[['英语 collaborate + -ive → collaborative','合作 → 以合作为特点的']],'collaborative writing 是共同写作；a collaborative person 愿意配合和一起想办法。它说明工作方式，不保证所有意见都完全一致。','a collaborative project；collaborative learning；a collaborative approach。','collective 强调群体整体；collaborative 更强调成员之间有实际协作。',('The course ends with a collaborative research project.','课程最后有一个合作研究项目。'),('We need a more collaborative approach to solving these problems.','解决这些问题需要更注重协作的方法。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/collaborative','https://en.wiktionary.org/wiki/collaborative#English']),
E('collaboratively','/kəˈlæbərətɪvli/','合作地；协同地','说的是任务怎样完成：参与者共同修改、讨论、贡献，而不只是挂上多个名字。','collaborative + -ly。',COLLAB+[['英语 collaborative + -ly → collaboratively','以协作方式']],'work collaboratively 是共同推进工作；write collaboratively 是一起构思、写作、修订。比 together 更明确说明有工作上的配合。','work collaboratively；develop collaboratively；write collaboratively。','together 也可以只是待在同一个地方；collaboratively 强调把工作协作起来。',('Students work collaboratively to test their ideas.','学生们协作测试各自的想法。'),('The guide was written collaboratively by teachers from five schools.','这份指南由五所学校的教师合作编写。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/collaboratively','https://en.wiktionary.org/wiki/collaboratively#English']),
E('elaborate','形容词 /ɪˈlæbərət/；动词 /ɪˈlæbəreɪt/','精心复杂的；详尽的；详细说明','花功夫把细节做出来：东西就显得精细复杂，讲话就变成把意思展开。','接拉丁 ex- + laborare → elaborare、elaboratus；形容词、动词分别借入。不是把名词 labor 直接变成现代英语 elaborate。',ELA,'an elaborate design 细节繁多，可能精美，也可能过于复杂。动词 elaborate on a point 是进一步解释一点。最实用的区别是形容词尾音 /ət/，动词尾音 /eɪt/。','an elaborate plan；elaborate decorations；elaborate on an idea。','detailed 只是细节多；elaborate 常多出精心安排或复杂铺陈。动词 elaborate 不等于毫无目的地啰嗦。',('The ceiling is covered with elaborate floral patterns.','天花板上布满了精细复杂的花卉图案。'),('Could you elaborate on the reasons for that decision?','你能进一步说明作出那个决定的理由吗？'),sources=['https://www.etymonline.com/word/elaborate','https://www.oxfordlearnersdictionaries.com/definition/english/elaborate_1','https://www.oxfordlearnersdictionaries.com/definition/english/elaborate_2']),
E('elaboration','/ɪˌlæbəˈreɪʃən/','详细阐述；展开；精细加工','把最初的一句话、一个构想逐步补成有细节的版本。','接晚期拉丁 elaboratio，也有法语 élaboration 的借入说明；英语名词早于 elaborate 的常见记录，不能只画英语动词加 -ion。',LV+[['拉丁 elaborare → 晚期拉丁 elaboratio；法语 élaboration','费力做出来 → 展开、加工的名词'],['英语 elaboration','历史早期有生理形成义，后常指详细展开']],'without further elaboration 是不再详细解释；an elaboration of an earlier idea 可以是旧构想发展出的更细方案。它强调展开，不只是把同一句再说一次。','further elaboration；an elaboration of an idea；need no elaboration。','explanation 重点是让人理解；elaboration 重点是补细节、扩展开，有时是解释的一部分。',('He rejected the proposal without further elaboration.','他否决了提议，没有进一步说明。'),('The new design is an elaboration of a much simpler earlier sketch.','这个新设计是在一张简单得多的早期草图基础上细化而成的。'),sources=['https://www.etymonline.com/word/elaboration','https://en.wiktionary.org/wiki/elaboration#English','https://www.oxfordlearnersdictionaries.com/definition/english/elaboration']),
E('elaborately','/ɪˈlæbərətli/','精心复杂地；细致繁复地','把细节一层层做足，呈现出花过很多功夫的样子。','形容词 elaborate + -ly；保留形容词的 /ət/，不是动词 /eɪt/ 的读音。',ELA+[['英语 elaborate〔形容词〕 + -ly → elaborately','精心复杂的 → 精细繁复地']],'elaborately carved 是雕得细致繁复；elaborately staged 是安排了很多细节的表演或场面。可以赞用心，也可能暗示做得太复杂。','elaborately decorated；elaborately carved；elaborately planned。','carefully 是小心、认真；elaborately 还强调复杂细节和精心铺排。',('The wooden screen was elaborately carved with birds and flowers.','木屏风上精细地雕着花鸟图案。'),('The surprise party had been elaborately planned for weeks.','这场惊喜派对花了好几周精心筹划。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/elaborately','https://en.wiktionary.org/wiki/elaborately#English']),
E('laborious','英 /ləˈbɔːriəs/；美 /ləˈbɔːriəs/','费时费力的；艰苦繁琐的','做一点就要花很多功夫，进展慢，不像顺手就能完成。','借自古法语 laborios，接拉丁 laboriosus；现代可联系 labor 与 -ious，但这个形容词先在拉丁、法语里形成。',LOR,'a laborious process 往往步骤多、耗精力。它通常形容任务、过程、方式；夸一个人勤奋，日常用 hardworking 更自然。','a laborious task；a laborious process；slow and laborious。','difficult 只是难；laborious 特别让人想到耗时、费劲、一步步磨出来。',('Checking every record by hand was a laborious task.','逐条人工核对记录是一项费时费力的工作。'),('The old software made even simple changes slow and laborious.','旧软件让简单改动也变得缓慢费劲。'),sources=['https://www.etymonline.com/word/laborious','https://www.oxfordlearnersdictionaries.com/definition/english/laborious']),
E('laboriously','英 /ləˈbɔːriəsli/；美 /ləˈbɔːriəsli/','费力地；吃力而缓慢地','每往前推进一点都费劲，能看出做事的人在下苦功。','laborious + -ly。',LOR+[['英语 laborious + -ly → laboriously','费力的 → 费力地进行']],'copy laboriously 是一笔笔吃力抄写；climb laboriously 是艰难攀爬。可以描述努力，但常让人感觉效率低或过程辛苦。','work laboriously；copy laboriously；laboriously reconstruct something。','carefully 不一定慢或吃力；laboriously 特别强调推进费劲。',('He laboriously copied the faded notes into a new notebook.','他费力地把褪色的笔记抄进新本子。'),('The researchers laboriously reconstructed the timeline from scattered records.','研究人员从零散记录中艰难地还原出时间线。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/laboriously','https://en.wiktionary.org/wiki/laboriously#English']),
]
C=[['拉丁语 candere','发亮、发白、发热发光']]
CANDID=C+[['拉丁语 candidus → 英语 candid','明亮、洁白 → 坦诚、不掩饰；后来也指未摆拍']]
CANDIDATE=C+[['拉丁语 candidus → candidatus → 英语 candidate','穿亮白袍的竞选者 → 参选人、候选人']]
CANDLE=C+[['拉丁语 candela → 古英语 candel → 英语 candle','发光的蜡烛；很早借入英语']]
CANDOR=C+[['拉丁语 candor → 英语 candor / candour','明亮、洁白 → 坦率、诚恳']]
INC=C+[['拉丁语 in- + candere → incendere','点燃；也比喻激起情绪']]
INCENSE=INC+[['名词支线：晚期拉丁 incensum → 古法语 encens → 英语 incense','烧起来发香的东西 → 香'],['动词支线另行借入：拉丁 incensare → 古法语 incenser → 英语 incense','点燃情绪 → 激怒；不由前一香名词派生']]
INCAND=C+[['拉丁语 candescere → incandescere → incandescens','开始发热发光 → 热到发光的']]
W += [
E('candidate','/ˈkændɪdət/，亦 /ˈkændɪdeɪt/','候选人；求职者；考生；可能适合的对象','已经被拿出来考虑，或者主动来争取某个位置的人或东西。','借自拉丁 candidatus，原指穿亮白袍竞选公职的人，接 candidus；不是现代英语 candid“坦率”加 -ate 就变成候选人。',CANDIDATE,'a job candidate 是求职候选人；a candidate for replacement 可以是可能要被替换的东西。历史上的白袍是命名背景，不表示今天每位候选人都坦诚。','a candidate for a post；a suitable candidate；interview candidates；exam candidates。','applicant 强调已经申请；candidate 强调正被考虑或参与竞争，两者范围可重叠。',('We interviewed five candidates for the position.','我们面试了五名该职位的候选人。'),('The old server is a strong candidate for replacement.','那台旧服务器很可能需要更换。'),sources=['https://www.etymonline.com/word/candidate','https://www.oxfordlearnersdictionaries.com/definition/english/candidate']),
E('candidacy','/ˈkændɪdəsi/','候选资格；参选；成为候选人的状态','焦点不再是那个人，而是他正在争取职位、接受考虑这件事。','candidate 的词基 + -cy，构成状态名词；不是 candid + -acy。',CANDIDATE+[['英语 candidate → candidacy','候选人 → 候选身份、参选活动']],'announce one’s candidacy 常说宣布参选；support someone’s candidacy 是支持其成为或担任某职位的候选人。也用于学位、职位资格，不只选举。','announce a candidacy；support somebody’s candidacy；candidacy for a post。','campaign 是为赢得支持而做的宣传行动；candidacy 是候选身份或参选本身。',('She announced her candidacy for the school board.','她宣布参选学校董事会成员。'),('Several colleagues supported his candidacy for department chair.','几位同事支持他竞任系主任。'),sources=['https://www.etymonline.com/word/candidacy','https://www.oxfordlearnersdictionaries.com/definition/english/candidacy']),
E('candidature','英 /ˈkændɪdətʃə/；美 /ˈkændɪdətʃər/','候选资格；候选人身份；参选','与 candidacy 基本同义，常出现在较正式、偏英式的选任文字中。','借自法语 candidature，由 candidat + -ure 构成；现代可联系 candidate，但不是必须在英语里才加上后缀。',C+[['拉丁 candidatus → 法语 candidat → candidature → 英语 candidature','候选人 → 候选身份、参选']],'support a candidature 是支持某人的参选或候选资格。日常和美式文字里 candidacy 往往更常见；不用为了正式而把 candidate 本人也改叫 candidature。','support a candidature；withdraw one’s candidature；candidature for office。','candidate 是人；candidature 与 candidacy 是人的候选身份或参选状态。',('The committee agreed to support her candidature.','委员会同意支持她的候选资格。'),('He withdrew his candidature before the final vote.','他在最后投票前退出了竞选。'),sources=['https://www.merriam-webster.com/dictionary/candidature','https://www.collinsdictionary.com/dictionary/english/candidature','https://www.oxfordlearnersdictionaries.com/definition/english/candidature']),
E('candid','/ˈkændɪd/','坦率的；直言不讳的；未摆拍的','把真实想法或自然状态露出来，没有先修饰成好看的样子。','借自拉丁 candidus“明亮、洁白”，古代已可比喻真诚；现代坦率义与摄影义有各自发展，不把白色当作人的品德判断。',CANDID,'a candid answer 是说实话、不绕弯；a candid photograph 是自然抓拍，不专门摆姿势。坦率不等于一定粗鲁，关键是没有刻意藏着。','be candid about something；a candid conversation；candid photographs。','blunt 常强调说得直、可能伤人；candid 强调真实坦诚。摄影中 candid 不等于偷拍，一张自然照片也可事先获同意。',('She was candid about the mistakes she had made.','她坦率地谈了自己犯过的错误。'),('I prefer candid photographs to carefully posed portraits.','比起精心摆拍的人像，我更喜欢自然抓拍的照片。'),sources=['https://www.etymonline.com/word/candid','https://www.oxfordlearnersdictionaries.com/definition/english/candid']),
E('candidly','/ˈkændɪdli/','坦率地；直说','说话时把真实判断摆出来，不绕着别人想听的话说。','candid + -ly。',CANDID+[['英语 candid + -ly → candidly','坦率的 → 坦率地表达']],'speak candidly about a problem 是不掩饰问题。句首 Candidly, ... 类似“坦白说”，常引出一个可能不好听的真实意见。','speak candidly；talk candidly about；candidly admit。','honestly 还可强调自己没有撒谎；candidly 更突出愿意把想法和难处公开说出来。',('The manager spoke candidly about the project’s delays.','经理坦率地谈了项目延期的问题。'),('Candidly, I do not think we have enough time to do this well.','坦白说，我觉得我们没有足够时间把这件事做好。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/candidly','https://en.wiktionary.org/wiki/candidly#English']),
E('candor','英 /ˈkændə/；美 /ˈkændər/','坦率；诚恳；直言〔美式常用拼写〕','不粉饰问题、愿意把真实情况说出来的态度。','直接接拉丁名词 candor，来自 candere；英语名词早于 candid 的常见记录，不是英语 candid 去掉词尾再现造。',CANDOR,'thank someone for their candor 是感谢对方说真话。坦率可以与礼貌并存，candor 本身不意味着嘴上毫无分寸。','speak with candor；appreciate somebody’s candor；unusual candor。','honesty 包含不欺骗、不作弊等更大范围；candor 尤其突出交流中的开诚布公。',('I appreciate your candor about the weaknesses in the proposal.','谢谢你坦率指出提案的不足。'),('The interview was notable for the candor of her answers.','这次访谈中，她回答得十分坦诚，令人印象深刻。'),sources=['https://www.etymonline.com/word/candor','https://www.merriam-webster.com/dictionary/candor']),
E('candour','英 /ˈkændə/；美 /ˈkændər/','坦率；诚恳〔英式常用拼写〕','把事实和看法敞开说，不让对方只看到经过包装的好消息。','与 candor 是同一个名词的地区拼写变体；拉丁 candor 的来源相同，-our 不是新的词缀。',CANDOR,'with refreshing candour 常赞某人难得直率。这个词通常不可数，说 her candour，不说 a candour 来指一次坦率发言。','with remarkable candour；a lack of candour；frankness and candour。','candour 与 candor 没有语义分工，主要按所用英语的拼写习惯选择。',('She described the failed experiment with refreshing candour.','她以难得的坦率描述了那次失败的实验。'),('The committee called for greater candour in future reports.','委员会要求今后的报告更加坦诚。'),sources=['https://www.etymonline.com/word/candour','https://www.oxfordlearnersdictionaries.com/definition/english/candour']),
E('candle','/ˈkændl/','蜡烛；用光照检视〔尤指蛋〕','靠烛芯燃烧来发光的一小段蜡；名字本来就接着发光这条线。','古英语已从拉丁 candela 借入；不是晚近才由 candid 改出来。动词 candle 是拿光透照查看，后来也可不用真蜡烛。',CANDLE+[['英语 candle〔名词〕 → candle〔动词〕','用烛光照看 → 用光透照检查']],'light a candle 是点蜡烛；blow out a candle 是吹灭。can’t hold a candle to 表示远远比不上，不是谈能不能拿住蜡烛。检查蛋的动词义比日常名词专门。','light a candle；blow out the candles；a scented candle；can’t hold a candle to。','candle 是光源本身；candlelight 是它发出的光，通常不可数。',('She lit a candle when the power went out.','停电后，她点了一支蜡烛。'),('This small speaker cannot hold a candle to the sound system downstairs.','这个小音箱远比不上楼下那套音响。'),sources=['https://www.etymonline.com/word/candle','https://www.oxfordlearnersdictionaries.com/definition/english/candle','https://www.merriam-webster.com/dictionary/candle']),
E('candlelight','/ˈkændllaɪt/','烛光','蜡烛发出的那团柔和、会轻轻跳动的光。','candle + light；古英语 candel lēoht 已有相应组合，不是最近才造的复合词。',CANDLE+[['古英语 candel lēoht → 英语 candlelight','蜡烛 + 光 → 烛光']],'by candlelight 是借烛光做事；in the candlelight 是处在烛光里。通常不可数，不把几支蜡烛的光数成 several candlelights。','by candlelight；in the candlelight；soft candlelight。','candlelight 是光的名词；candlelit 是被烛光照亮的形容词。',('They had dinner by candlelight on the balcony.','他们在阳台上伴着烛光吃了晚餐。'),('The silver bowl gleamed in the candlelight.','银碗在烛光中微微发亮。'),sources=['https://en.wiktionary.org/wiki/candlelight#English','https://www.oxfordlearnersdictionaries.com/definition/english/candlelight']),
E('candlelit','/ˈkændllɪt/','烛光照亮的；在烛光中进行的','用烛光给房间或场景染上一层光。','candle + lit，lit 是 light“照亮”的过去分词；不是 candlelight 简单变过去式。',CANDLE+[['英语 candle + lit → candlelit','蜡烛 + 被照亮的 → 烛光照明的']],'a candlelit room 是点烛照亮的房间；a candlelit dinner 是在烛光下吃的晚饭。这个词描述照明场景，温馨或浪漫只是常见联想。','a candlelit dinner；a candlelit room；a candlelit procession。','candlelight 是烛光本身；candlelit 用来修饰被这种光照着的人、地方或活动。',('We walked into a quiet, candlelit room.','我们走进一间安静、由烛光照亮的房间。'),('The hotel arranged a candlelit dinner in the garden.','酒店在花园安排了一顿烛光晚餐。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/candlelit','https://en.wiktionary.org/wiki/candlelit#English']),
E('candlestick','/ˈkændlstɪk/','烛台；蜡烛形价格图柱','把蜡烛稳稳托住的器具；图表里的同名形状看起来像一段烛身带着细芯。','candle + stick；古英语 candelsticca 已有。金融图表义是后来按形状命名，不表示古代烛台直接变成交易工具。',CANDLE+[['古英语 candelsticca → 英语 candlestick','托蜡烛的支架'],['形状比喻：图表中的 candlestick','用烛身和细线表示一个时段的价格信息']],'日常 a brass candlestick 是黄铜烛台。图表中每根 candlestick 通常综合开盘、收盘、最高和最低价格；各部分标出这些不同的价格位置。','a silver candlestick；a pair of candlesticks；a candlestick chart。','candle 是蜡烛；candlestick 通常是托它的器具。图表义需结合金融语境。',('A pair of brass candlesticks stood on the shelf.','架子上摆着一对黄铜烛台。'),('Each candlestick on this chart represents one day of trading.','这张图上的每根蜡烛柱代表一天的交易。'),sources=['https://en.wiktionary.org/wiki/candlestick#English','https://www.oxfordlearnersdictionaries.com/definition/english/candlestick']),
E('incense','名词 /ˈɪnsens/；激怒义动词 /ɪnˈsens/','香；香的烟气；激怒','同一条点燃支线，一边点燃香料，一边比喻把人的怒火点起来。','名词来自晚期拉丁 incensum，经古法语 encens；激怒义动词来自拉丁 incensare，经古法语 incenser。两条借入路线分开，不是因为讨厌香味才产生激怒义。',INCENSE,'burn incense 是焚香，incense 常不可数；a stick of incense 是一支香。激怒义常见于 be incensed by，重音在后。另有用香熏的动词义，与激怒义也要分清。','burn incense；incense sticks；the smell of incense；incense somebody。','香名词前重音，激怒动词后重音；in- 在这里不是否定，不能理解成不闻香。',('The room smelled faintly of incense.','房间里有一股淡淡的香气。'),('The dismissive reply incensed the customers.','那种敷衍的回复激怒了顾客。'),sources=['https://www.etymonline.com/word/incense','https://www.oxfordlearnersdictionaries.com/definition/english/incense_1','https://www.oxfordlearnersdictionaries.com/definition/english/incense_2']),
E('incensed','/ɪnˈsenst/','非常愤怒的；被激怒的','怒火已经被点着，不是有点不高兴。','incense 的激怒义 + -ed；词尾读 /t/，重音仍在后一个音节。',INC+[['拉丁 incensare → 古法语 incenser → 英语 incense〔激怒〕','点燃情绪 → 激怒'],['英语 incense + -ed → incensed','被激怒的 → 十分愤怒的']],'be incensed at/by/about something 常把愤怒原因接出来。它比 annoyed 强，语体也稍正式，常用于新闻或强烈反应。','incensed by a remark；incensed at the decision；absolutely incensed。','incensed 这里不是香熏过的；常用形容词义直接接激怒动词。',('Residents were incensed by the sudden cancellation of the bus service.','公交服务突然取消，居民们十分愤怒。'),('She was incensed that her complaint had been ignored.','她的投诉被无视了，这让她非常愤怒。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/incensed','https://www.etymonline.com/word/incensed']),
E('incendiary','英 /ɪnˈsendiəri/；美 /ɪnˈsendieri/','纵火的；易引起燃烧的；煽动性的；纵火者','字面是能点火，比喻是能把人群的怒气或冲突点起来。','接拉丁 incendium“火灾、燃烧”与 incendiarius，经法语或拉丁语借入；最终接 incendere“点燃”。',INC+[['拉丁 incendium → incendiarius → 英语 incendiary；也有法语 incendiaire 路线','引起火的 → 纵火的；煽动情绪的']],'incendiary remarks 指容易激起强烈对立的言论；字面可说引燃物、纵火行为。不是所有有激情的话都叫 incendiary，它常带危险、挑动冲突的评价。','incendiary language；incendiary remarks；an incendiary speech。','inflammatory 也常说煽动言论；incendiary 保留更鲜明的点火联想，也有字面燃烧义。',('The editor removed several incendiary remarks from the article.','编辑删去了文中几处煽动性的言论。'),('Investigators concluded that the fire was of incendiary origin.','调查人员认定这场火灾由人为纵火造成。'),sources=['https://www.etymonline.com/word/incendiary','https://www.oxfordlearnersdictionaries.com/definition/english/incendiary_1','https://en.wiktionary.org/wiki/incendiary#English']),
E('incandescent','英 /ˌɪnkænˈdesnt/；美 /ˌɪnkənˈdesnt/','白炽的；热得发光的；光彩夺目的；极愤怒的','像金属热到自己发光，也可比喻才华耀眼或怒气烧得炽烈。','来自拉丁 incandescens，可能经法语 incandescent；candescere 是开始发光、发白，in- 在这里不是不。',INCAND+[['法语 incandescent 或直接拉丁借入 → 英语 incandescent','因热发光的 → 耀眼、怒不可遏的']],'an incandescent bulb 让灯丝受热发光；不等于所有明亮灯泡。incandescent with rage 是怒不可遏；an incandescent performance 则赞表演光彩夺目。','an incandescent bulb；incandescent with rage；incandescent brilliance。','fluorescent 是荧光的，发光机制不同。incandescent 的白炽名称不要求眼睛看到的光总是纯白色。',('The lamp still uses an incandescent bulb.','这盏灯还在使用白炽灯泡。'),('He was incandescent with rage when he discovered the deception.','发现自己受骗后，他怒不可遏。'),sources=['https://www.etymonline.com/word/incandescent','https://www.oxfordlearnersdictionaries.com/definition/english/incandescent']),
E('incandescence','英 /ˌɪnkænˈdesns/；美 /ˌɪnkənˈdesns/','白炽；热致发光；耀眼的光辉','材料因为温度升高而发出可见光，像热灯丝亮起来。','借自法语 incandescence，接 incandescent 一系；英语名词早于形容词 incandescent 的常见记录，不把它画成英语形容词后来换后缀。',INCAND+[['法语 incandescence → 英语 incandescence','发热发光的状态；英语早期也有情绪炽烈的比喻义']],'incandescence 讲的是发光现象，不是灯泡这个物品；也可用于文学，比喻耀眼的光彩。发光颜色会随温度等条件变化，不必一开始就是白色。','heated to incandescence；the incandescence of a filament；a glow of incandescence。','luminescence 通常指不以受热为主因的发光；incandescence 的关键是因高温而发光。',('The wire was heated to incandescence during the demonstration.','演示中，金属丝被加热到发光。'),('The old bulb produced light by incandescence rather than fluorescence.','那只旧灯泡靠热致发光，而不是荧光来照明。'),sources=['https://www.etymonline.com/word/incandescence','https://www.oxfordlearnersdictionaries.com/definition/english/incandescence','https://www.nist.gov/si-redefinition/candela']),
E('candela','/kænˈdiːlə/，亦 /kænˈdelə/','坎德拉〔发光强度单位，符号 cd〕','量一个光源朝某个方向发光有多强，名字借用了蜡烛，但不是随手拿一支蜡烛当标准。','现代科学单位名借自拉丁 candela“蜡烛”；与 candle 是不同时期的借词，不由现代英语 candle 改拼得到。',C+[['拉丁语 candela → 现代科学单位 candela','蜡烛 → 标准化的发光强度单位']],'candela 是发光强度单位，关注方向；lumen 是光通量单位，关注总的可见光输出。现代定义有精确标准，不等于任何一支蜡烛都恰好一坎德拉。','measured in candelas；luminous intensity；the symbol cd。','candela 不是瓦特，也不是照度单位 lux。名字像 candle，不代表它是在数蜡烛。',('Luminous intensity is measured in candelas.','发光强度以坎德拉为单位。'),('The symbol for the candela is cd.','坎德拉的单位符号是 cd。'),sources=['https://www.nist.gov/si-redefinition/candela','https://www.oxfordlearnersdictionaries.com/definition/english/candela']),
]
DEFERRED={'restrictor':'较专门装置名，暂缓。','constringe':'罕用动词，优先掌握 constrain、constrict。','elaborative':'较专门或低频形容词，先学 elaborate。','elaborator':'低频人物或工具派生名词，暂缓。','candler':'专门照蛋人员、器具或古旧蜡烛匠名称，暂缓。'}
STRING_ROOT=dict(id='C1437',meaning='拉紧、捆紧；严格、限制与压力',core='像把松绳收紧：规则因此不松口，行动因此受限，材料或人也可能被绷得吃力。',image='stringere 拉紧 → strict、stringent；restringere 拉回约束 → restrict、restrain；constringere 一起捆紧 → constrain、constrict；古法语支线 → strain、stress、distress。',intro='词根来自拉丁 stringere，strict- 对应 strictus，stringent- 对应现在分词形式。同一源头可沿法语和拉丁直接借入形成不同词。strain 的品种、菌株义另接古英语 strēon，保留在词条里辨清，不纳入拉紧支线。',forms='restriction、restrictive、constriction 各有较早独立借入历史，不全由现代英语动词现加后缀。constrict 还有由 constriction 反构的解释。stress 名动词分别保留法语借入与 distress 缩短路线。英语 string“绳子”是日耳曼语来源，不能直接当作本页拉丁词根的英文祖先。',branches=[['严格与标准','strict, strictly, strictness, stringent, stringently, stringency'],['限定范围','restrict, restriction, restrictive, restricted, unrestricted'],['环境约束与实际缩窄','constrain, constraint, constrained, unconstrained, constrict, constriction'],['收住行为、情绪','restrain, restraint, restrained, unrestrained'],['压力、痛苦、用力与过滤','strain, strained, strainer, stress, stressful, stressed, distress, distressing, distressed'],['涩口、收敛与尖锐','astringent, astringency']],contrasts='stressful 是事情令人紧张，stressed 是人承受压力；distressing 使人痛苦，distressed 是已经痛苦。restrictive 施加限制，restricted 承受限制。力学里的 stress 与 strain 分别是应力与应变，不能按日常压力一概互译。',practice='分别用 restrict、restrain、constrict 描述限定访问、忍住笑和通道变窄；用两句话区分 strain 的预算压力义与菌株义。',words=[w for w in ASSIGN['roots'][68]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][68]['family'] if w in DEFERRED})
LABOR_ROOT=dict(id='C0641',meaning='劳动、费力；共同工作与细致展开',core='花时间和力气把事做出来：一起费力就是合作，把细节费心做足就是精细复杂，专门做实验的工作场所成了实验室。',image='labor 辛劳 → labor / labour；laborare 工作 → laboratory；com- 一起 + laborare → collaborate 家族；ex- 做出来 + laborare → elaborate 家族。',intro='拉丁 labor 的更早来源不确定，不强行接到滑倒或摇晃。labor、labour 是地区拼写变体，名动词借入各有法语路径。collaborator 与 collaboration 在英语里早于 collaborate；elaboration 也不能只当作英语 elaborate 后来加后缀。',forms='coll- 是 con- 在 l 前的同化形式，表示一起。elaborate 形容词尾读 /ət/，动词尾读 /eɪt/。laboratory 英美常用重音位置不同。lab 主要缩自 laboratory，但狗的 Lab 缩自 Labrador，另算来源。',branches=[['劳动、劳动力与劳动者','labor, labour, laborer, labourer'],['实验室与简短叫法','laboratory, lab'],['共同工作','collaborate, collaboration, collaborator, collaborative, collaboratively'],['细节展开与精心制作','elaborate, elaboration, elaborately'],['费时费力','laborious, laboriously']],contrasts='laborious 突出费时费劲，elaborate 突出精细复杂；精细的东西不一定做起来特别费劲。collaborator 是实际合作的人，colleague 只是同事关系。labour 与 labor 不作语义区分。',practice='用 elaborate 的两种词性描述精细设计与详细说明；用 laboratory 的英美读法各读一次，并解释 collaborative work 与只是在同一办公室的区别。',words=[w for w in ASSIGN['roots'][69]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][69]['family'] if w in DEFERRED})
CAND_ROOT=dict(id='C0167',meaning='发亮、发热发光；坦率、候选人与燃烧支线',core='从亮起来出发：蜡烛照亮空间，白袍曾标出竞选者，明亮透明成为坦率的旧比喻；点燃又能指香料燃烧和怒火升起。',image='candere 发亮 → candela 蜡烛 → candle；candidus 明亮 → candid、candor；candidatus 白袍竞选者 → candidate；incendere 点燃 → incense、incendiary；incandescere 热到发光 → incandescent。',intro='cand-、cend- 在这些词中接拉丁发亮、发热的相关形式。candidate 的白袍来自古罗马竞选背景，不是在说现代候选人的品德。candid 的坦率和未摆拍义可以用不掩饰来联系，但不能把现代联想当作所有历史细节。',forms='incense 名词香通常前重音，激怒动词后重音；两者经不同法语形式借入。candor / candour 是拼写变体，名词有独立拉丁来源。incandescence 在英语里的记录早于 incandescent，不能把现代后缀对照画成确定的先后。candle 是很早的借词，candela 是现代单位名的再次借入。',branches=[['候选人及候选身份','candidate, candidacy, candidature'],['坦率、自然、不掩饰','candid, candidly, candor, candour'],['烛光与器具','candle, candlelight, candlelit, candlestick'],['点燃与激怒','incense, incensed, incendiary'],['热致发光与测量','incandescent, incandescence, candela']],contrasts='candid 不等于粗鲁，candid photograph 不必是偷拍。candlelight 是光，candlelit 是被光照亮的。candela、lumen、lux 分别用于发光强度、光通量、照度，不能因为都和光有关就互换。',practice='读出 incense 的两个重音位置；用 candid 形容回答和照片；解释 candidate 为什么属于发亮这组，而不是现代英语坦率加后缀。',words=[w for w in ASSIGN['roots'][70]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][70]['family'] if w in DEFERRED})
roots=[STRING_ROOT,LABOR_ROOT,CAND_ROOT]
expected={w for r in ASSIGN['roots'][68:71] for w in r['family'] if w in set(ASSIGN['owned_words']) and w not in DEFERRED}
assert {w['word'] for w in W}==expected,({w['word'] for w in W}-expected,expected-{w['word'] for w in W})
assert len(W)==len({w['word'] for w in W})
assert all(len(w['examples'])>=2 and all(len(e)==2 and all(e) for e in w['examples']) for w in W)
assert all(all(w.get(k) for k in ['ipa','meaning','sense','split','history','explanation','usage','contrast','sources']) for w in W)
assert all(all(len(h)==2 and all(h) for h in w['history']) for w in W)
for kind,data in [('roots',roots),('words',W)]: (OUT/f'{kind}_batch200_st_22.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
(OUT/'words_batch200_st_22_working.json').unlink(missing_ok=True)
p=Path('.cache/batch200/rewrite_st_progress.json');progress=json.loads(p.read_text())
progress['completed_roots']=list(dict.fromkeys(progress['completed_roots']+[r['id'] for r in roots]))
progress['completed_words']=list(dict.fromkeys(progress['completed_words']+[w['word'] for w in W]))
progress['batches']=list(dict.fromkeys(progress['batches']+['batch200_st_22']))
progress.setdefault('deferred_words',{}).update(DEFERRED)
progress.update(next_root_index=71,next_root_id=ASSIGN['roots'][71]['id'],status='writing',active_script=None,active_written_words=0,active_note='st22 string32/labor16/cand17=65 new words;5 rare derivatives deferred. Selfreview complete;frozen. Next resid shared,mon,urb,grav.')
p.write_text(json.dumps(progress,ensure_ascii=False,indent=2)+'\n')
print('st22',len(roots),'roots',len(W),'words',sum(len(w['examples']) for w in W),'examples',len(DEFERRED),'deferred')
